import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Plateaus","description":"","frontmatter":{"title":"Plateaus","covers":{"screens":["SCR-065","SCR-066"],"stories":["US-084","US-085","US-086","US-087","US-088","US-089","US-155","US-157"]}},"headers":[],"relativePath":"usage/plateaus.md","filePath":"usage/plateaus.md"}`),a={name:`usage/plateaus.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="plateaus" tabindex="-1">Plateaus <a class="header-anchor" href="#plateaus" aria-label="Permalink to “Plateaus”">​</a></h1><p>A plateau is a named, stable state of your architecture. The <strong>baseline</strong> is the architecture in production today. <strong>Target</strong> and <strong>transition</strong> plateaus describe planned states: a target state, and intermediate states on the way to it. <a href="./solutions">Solutions</a> can work toward a plateau.</p><p>There is no switch for plateau mode: it starts when you create the first baseline. Solutions without a plateau keep working as before.</p><p>You need the permission <code>plateau:write</code> (for example the role <code>enterprise-architect</code>) to create and edit plateaus. To see them, <code>plateau:write</code>, <code>plateau:go-live</code> or <code>solution:write</code> is enough (see <a href="./../administration/roles-and-permissions">Roles and permissions</a>).</p><h2 id="the-page-plateaus" tabindex="-1">The page Plateaus <a class="header-anchor" href="#the-page-plateaus" aria-label="Permalink to “The page Plateaus”">​</a></h2><p>Choose <em>Plateaus</em> in the header. The page shows:</p><ul><li>the <strong>baseline</strong>, highlighted, with the date since when it is valid;</li><li>the <strong>target and transition plateaus</strong>, by planned date, each with its predecessor, its basis and the number of solutions that work toward it. Without one, the page says &quot;No target plateau planned yet&quot;;</li><li>the <strong>realized plateaus</strong>, collapsed, newest first. A plateau becomes realized when its successor goes live.</li></ul><h2 id="create-the-initial-baseline" tabindex="-1">Create the initial baseline <a class="header-anchor" href="#create-the-initial-baseline" aria-label="Permalink to “Create the initial baseline”">​</a></h2><p>Without a baseline, the page says &quot;No baseline plateau exists yet&quot;. Choose <em>Create initial baseline</em>, enter a name such as &quot;Baseline 2026-Q2&quot; and, optionally, a description and the date of the state, and choose <em>Create plateau</em>. There is only ever one baseline.</p><h2 id="create-a-target-or-transition-plateau" tabindex="-1">Create a target or transition plateau <a class="header-anchor" href="#create-a-target-or-transition-plateau" aria-label="Permalink to “Create a target or transition plateau”">​</a></h2><ol><li><p>Choose <em>New plateau</em>.</p></li><li><p>Fill in the dialog:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required, up to 255 characters, unique regardless of upper and lower case</td></tr><tr><td>Type</td><td><em>Target</em> or <em>Transition</em></td></tr><tr><td>Description</td><td>optional, up to 2000 characters</td></tr><tr><td>Valid from</td><td>optional: the planned go-live date</td></tr><tr><td>Predecessor</td><td>the plateau this one follows; the baseline is preselected. A realized plateau cannot be a predecessor</td></tr><tr><td>Basis</td><td>what the solutions of this plateau start from (see below)</td></tr></tbody></table></li><li><p>Choose <em>Create plateau</em>.</p></li></ol><h3 id="basis" tabindex="-1">The basis <a class="header-anchor" href="#basis" aria-label="Permalink to “The basis”">​</a></h3><p>The basis decides what a solution that works toward the plateau sees as its baseline:</p><ul><li><strong>Current catalog:</strong> the catalog as it is now.</li><li><strong>Content of the predecessor:</strong> the predecessor plateau with the changes of its active solutions applied. An entity that a solution of the predecessor retires is marked <em>Retiring by …</em>, a new entity it proposes is marked <em>Proposed by …</em>, and changed names and values show their planned value. A proposed entity cannot be changed or retired yet, because it does not exist before its go-live. If the predecessor itself has the basis &quot;content of the predecessor&quot;, its own predecessor counts as well.</li></ul><p>When two solutions of the same plateau change the same field, the change made last counts.</p><h2 id="edit-a-plateau" tabindex="-1">Edit a plateau <a class="header-anchor" href="#edit-a-plateau" aria-label="Permalink to “Edit a plateau”">​</a></h2><p>Choose <em>Edit</em> next to a plateau to change its name, description, date, predecessor or basis. The type changes only through the go-live. The predecessor is fixed as soon as a solution works toward the plateau.</p><p>A realized plateau is read-only: it has no <em>Edit</em>, and the API answers &quot;Realized plateau is read-only&quot;.</p><h2 id="go-live" tabindex="-1">Take a plateau live <a class="header-anchor" href="#go-live" aria-label="Permalink to “Take a plateau live”">​</a></h2><p>When the planned state is reached, the plateau goes live: it becomes the new baseline, the old baseline is realized, and the changes of its solutions reach the catalog. You need the permission <code>plateau:go-live</code> (for example the role <code>enterprise-architect</code>).</p><p>Only the plateau that follows the baseline directly can go live; it shows <em>Go live</em>. The dialog <em>Take plateau live</em> shows:</p><ul><li>which plateau becomes the baseline and which is realized;</li><li>how many entities are created, changed and retired;</li><li>the solutions that go live with the plateau;</li><li>warnings, which do not stop the go-live: solutions not yet approved, and the open issues the go-live will leave.</li></ul><p>Type the exact name of the plateau, then choose <em>Confirm go-live</em>. The go-live cannot be undone.</p><p>All active solutions of the plateau go live in one step, in the order in which their changes were last edited, each as a single <a href="./solutions#go-live">solution goes live</a>. If a field a solution changes was changed meanwhile, in the catalog or by a solution that goes live before it, the dialog lists the conflict at that solution; <em>Resolve</em> opens <em>Resolve conflicts</em>. Until every conflict is resolved, nothing goes live. If anything fails during the go-live, nothing changes.</p><p>After the go-live:</p><ul><li>the plateau is the baseline from today, and the old baseline is realized until today and read-only;</li><li>the solutions of the plateau are <em>Implemented</em>, and retired entities are deleted from the catalog;</li><li>plateaus that followed the old baseline now follow the new one, and their solutions start from it.</li></ul><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><p><code>GET /api/v1/plateaus</code> lists the plateaus, <code>POST /api/v1/plateaus</code> creates one, and <code>GET</code> and <code>PUT /api/v1/plateaus/{id}</code> read and edit one. <code>GET /api/v1/plateaus/{id}/go-live</code> shows what the go-live would do, and <code>POST</code> with the name of the plateau takes it live. Creating, editing and the go-live are audited as <code>plateau.created</code>, <code>plateau.updated</code> and <code>plateau.went-live</code>.</p>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};